/**
 * Pads a UTF-8 string to the given byte length (Compact pad semantics).
 */
export const padBytes = (length: number, value: string): Uint8Array => {
  const bytes = new Uint8Array(length);
  const encoded = new TextEncoder().encode(value);
  bytes.set(encoded.slice(0, length));
  return bytes;
};

/**
 * Generates a buffer containing a series of randomly generated bytes.
 */
export const randomBytes = (length: number): Uint8Array => {
  const bytes = new Uint8Array(length);
  crypto.getRandomValues(bytes);
  return bytes;
};
